          }
        }
      `}</style>
    </div>
  );
}","import React from 'react';

export default function CourseProgress({ inProgress, completed, onRefresh }) {
  return (
    <div className="course-progress-section">
      <div className="section-header">
        <h2 className="section-title">Course Progress</h2>
        <button onClick={onRefresh} className="refresh-btn">
          🔄 Refresh
        </button>
      </div>

      <div className="progress-tabs">
        <div className="tab-content">
          <h3>Courses in Progress ({inProgress.length})</h3>
          {inProgress.length > 0 ? (
            <div className="courses-list">
              {inProgress.map(enrollment => {
                const courseName = typeof enrollment.course === 'object' 
                  ? enrollment.course.display_value 
                  : enrollment.course;
                const progress = enrollment.progress_percentage || 0;

                return (
                  <div key={enrollment.sys_id.value || enrollment.sys_id} className="course-item">
                    <div className="course-info">
                      <h4>{courseName}</h4>
                      <div className="progress-bar">
                        <div className="progress-fill" style={{ width: `${progress}%` }}></div>
                      </div>
                      <span className="progress-text">{progress}% complete</span>
                    </div>
                  </div>
                );
              })}
            </div>
          ) : (
            <div className="empty-state">
              <p>📖 No courses in progress</p>
            </div>
          )}

          <h3>Completed Courses ({completed.length})</h3>
          {completed.length > 0 ? (
            <div className="courses-list">
              {completed.map(enrollment => {
                const courseName = typeof enrollment.course === 'object' 
                  ? enrollment.course.display_value 
                  : enrollment.course;
                const grade = enrollment.final_grade;
                const completionDate = enrollment.completion_date;

                return (
                  <div key={enrollment.sys_id.value || enrollment.sys_id} className="course-item completed">
                    <div className="course-info">
                      <h4>{courseName}</h4>
                      <div className="completion-details">
                        <span className="completion-date">Completed: {completionDate}</span>
                        {grade && <span className="final-grade">Grade: {grade}%</span>}
                      </div>
                    </div>
                    <div className="completion-badge">✅</div>
                  </div>
                );
              })}
            </div>
          ) : (
            <div className="empty-state">
              <p>🎓 No completed courses yet</p>
            </div>
          )}
        </div>
      </div>

      <style jsx>{`
        .progress-tabs {
          margin-top: 20px;
        }

        .tab-content h3 {
          color: #2d3748;
          margin: 30px 0 15px 0;
          padding-bottom: 8px;
          border-bottom: 2px solid #e2e8f0;
        }

        .courses-list {
          display: flex;
          flex-direction: column;
          gap: 15px;
        }

        .course-item {
          background: white;
          border: 1px solid #e2e8f0;
          border-radius: 8px;
          padding: 20px;
          display: flex;
          justify-content: space-between;
          align-items: center;
        }

        .course-info {
          flex: 1;
        }

        .course-info h4 {
          margin: 0 0 10px 0;
          color: #2d3748;
        }

        .progress-bar {
          height: 8px;
          background: #e2e8f0;
          border-radius: 4px;
          margin: 10px 0;
          overflow: hidden;
        }

        .progress-fill {
          height: 100%;
          background: linear-gradient(90deg, #667eea, #764ba2);
          transition: width 0.3s ease;
        }

        .progress-text {
          font-size: 0.9rem;
          color: #667eea;
          font-weight: 600;
        }

        .completion-details {
          display: flex;
          gap: 15px;
          font-size: 0.9rem;
          color: #718096;
        }

        .final-grade {
          color: #667eea;
          font-weight: 600;
        }

        .completion-badge {
          font-size: 1.5rem;
        }

        .empty-state {
          text-align: center;
          padding: 40px;
          color: #718096;
        }
      `}</style>
    </div>
  );
}","import React, { useState } from 'react';
import { StudentDashboardService } from '../../services/StudentDashboardService.js';

export default function Certificates({ certificates, onRefresh }) {
  const [downloading, setDownloading] = useState(new Set());
  const service = new StudentDashboardService();

  const handleDownload = async (certificate) => {
    const certId = typeof certificate.sys_id === 'object' ? certificate.sys_id.value : certificate.sys_id;

    try {
      setDownloading(prev => new Set([...prev, certId]));
      await service.downloadCertificate(certId);
    } catch (error) {
      console.error('Download failed:', error);
      alert('Failed to download certificate. Please try again.');
    } finally {
      setDownloading(prev => {
        const newSet = new Set(prev);
        newSet.delete(certId);
        return newSet;
      });
    }
  };

  if (certificates.length === 0) {
    return (
      <div className="certificates-section">
        <div className="section-header">
          <h2 className="section-title">My Certificates</h2>
          <button onClick={onRefresh} className="refresh-btn">
            🔄 Refresh
          </button>
        </div>

        <div className="empty-state">
          <div className="empty-state-icon">🏆</div>
          <h3>No Certificates Yet</h3>
          <p>Complete courses to earn certificates of completion</p>
        </div>
      </div>
    );
  }

  return (
    <div className="certificates-section">
      <div className="section-header">
        <h2 className="section-title">My Certificates ({certificates.length})</h2>
        <button onClick={onRefresh} className="refresh-btn">
          🔄 Refresh
        </button>
      </div>

      <div className="certificates-grid">
        {certificates.map(certificate => {
          const certId = typeof certificate.sys_id === 'object' ? certificate.sys_id.value : certificate.sys_id;
          const courseName = typeof certificate.course === 'object' 
            ? certificate.course.display_value 
